-- ============================================================
-- Migration 006 — Kategori ağacı ONARIM (UUID'den bağımsız, hosting-uyumlu)
-- Bozuk/yetim parent bağlarını KODA göre yeniden kurar. Geçici tablo YOK,
-- INSERT...SELECT YOK → paylaşımlı hosting (MariaDB) 1093/privilege sorunu yok.
-- İDEMPOTENT: iki kez çalıştırmak zarar vermez. Uygula: phpMyAdmin > SQL > Git.
-- SONRA: her cihazda sert yenile + çıkış/giriş (veya Ayarlar 'Sunucudan yenile').
-- ============================================================
SET NAMES utf8mb4;
SET @tenant := (SELECT id FROM tenants ORDER BY created_at ASC LIMIT 1);
SET @now := CURRENT_TIMESTAMP(3);

-- 1) Mevcut tüm kategorileri soft-delete (yeni ağaçta olanlar 2. adımda dirilir)
UPDATE categories SET deleted_at=@now, updated_at=@now
 WHERE tenant_id=@tenant AND deleted_at IS NULL;

-- 2) Sabit VALUES ile upsert. (tenant,code) çakışınca MEVCUT satır güncellenir
