  name_tr=VALUES(name_tr), name_en=VALUES(name_en), sku_template=VALUES(sku_template),
  default_count_mode=VALUES(default_count_mode), attribute_schema=VALUES(attribute_schema),
  sort_order=VALUES(sort_order), parent_id=NULL, updated_at=@now, deleted_at=NULL;

-- 3) parent_id'yi KOD üzerinden bağla (ASIL ONARIM). Satır-içi türetilmiş tablo m
--    (kod→üst_kod) ile self-join UPDATE — geçici tablo gerekmez, categories'i
--    alt sorguda değil JOIN'de okur (1093 yok). Kökler m'de yok → parent_id NULL kalır.
