  JOIN categories p ON p.tenant_id=@tenant AND p.code=m.pcode AND p.deleted_at IS NULL
SET c.parent_id = p.id, c.updated_at=@now
 WHERE c.tenant_id=@tenant AND c.deleted_at IS NULL;

-- 4) Ağaçta artık olmayan (silik) kategoriye bağlı parçaları serbest bırak
UPDATE parts pt JOIN categories c ON c.id=pt.category_id
   SET pt.category_id=NULL, pt.updated_at=@now
 WHERE pt.tenant_id=@tenant AND c.deleted_at IS NOT NULL;

